from fastapi import FastAPI, WebSocket, WebSocketDisconnect

app = FastAPI()

rooms = {}

@app.websocket("/ws/{room}")
async def chat_room(websocket: WebSocket, room: str):
    await websocket.accept()
    if room not in rooms:
        rooms[room] = []
    rooms[room].append(websocket)
    # Send welcome to the new client only
    await websocket.send_text(f'{{"system": "You joined room {room}"}}')
    # Notify others
    for conn in rooms[room]:
        if conn != websocket:
            await conn.send_text(f'{{"system": "User joined"}}')
    try:
        while True:
            data = await websocket.receive_text()
            # Broadcast to everyone else in the room
            for conn in rooms[room]:
                if conn != websocket:
                    await conn.send_text(data)
    except WebSocketDisconnect:
        rooms[room].remove(websocket)
        if not rooms[room]:
            del rooms[room]
        else:
            for conn in rooms[room]:
                await conn.send_text(f'{{"system": "User left"}}')
